  for (const item of items) {
    const name = item.section || "Other";
    let bucket = sections.find((s) =&gt; s.name === name);
    if (!bucket) {
      bucket = { name: name, items: [] };
      sections.push(bucket);
    }
    bucket.items.push(item);
  }
